head.b:skin:
:root {
    --bg: #0c0d10;
    --card: #16181d;
    --holo: #a5f3fc; /* Cyan-ish Holographic */
    --industrial: #334155;
    --text: #f8fafc;
    --border: rgba(255, 255, 255, 0.05);
}

body { 
    background: var(--bg); 
    color: var(--text); 
    font-family: 'Plus Jakarta Sans', sans-serif; 
    margin: 0; 
    padding: 20px; 
    transition: 0.5s cubic-bezier(0.4, 0, 0.2, 1); 
}

.container { max-width: 1250px; margin: 0 auto; transition: 0.5s; }

/* Zen Focus Mode */
.zen-active .config-panel { opacity: 0; pointer-events: none; transform: scale(0.98); display: none; }
.zen-active .main-grid { grid-template-columns: 1fr; }
.zen-active .container { max-width: 850px; }

header { 
    display: flex; 
    justify-content: space-between; 
    align-items: center; 
    border-bottom: 1px solid var(--border); 
    padding-bottom: 25px; 
    margin-bottom: 40px; 
}
.brand h1 { margin: 0; font-size: 1.5rem; letter-spacing: -1px; font-weight: 800; text-transform: uppercase; }
.brand h1 span { color: var(--holo); }
.brand p { margin: 0; font-size: 0.6rem; font-weight: 900; color: #475569; letter-spacing: 4px; text-transform: uppercase; }

.main-grid { display: grid; grid-template-columns: 380px 1fr; gap: 35px; }

.config-panel { 
    background: var(--card); 
    border-radius: 24px; 
    padding: 35px; 
    border: 1px solid var(--border); 
    position: sticky; 
    top: 20px; 
    height: fit-content;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.zen-trigger { 
    background: transparent; 
    color: var(--holo); 
    border: 1px solid var(--holo); 
    padding: 8px 22px; 
    border-radius: 30px; 
    font-size: 0.65rem; 
    font-weight: 900; 
    cursor: pointer; 
    transition: 0.3s;
}
.zen-trigger:hover { background: var(--holo); color: #000; box-shadow: 0 0 20px rgba(165, 243, 252, 0.4); }

label { 
    display: block; 
    font-size: 0.6rem; 
    font-weight: 800; 
    color: var(--industrial); 
    text-transform: uppercase; 
    letter-spacing: 2px; 
    margin: 20px 0 8px 0; 
}

input, select { 
    width: 100%; 
    background: #090a0c; 
    border: 1px solid #1e293b; 
    color: white; 
    padding: 15px; 
    border-radius: 12px; 
    font-size: 0.85rem; 
    box-sizing: border-box; 
    outline: none;
}
input:focus { border-color: var(--holo); }

.btn-forge { 
    width: 100%; 
    background: var(--holo); 
    color: #000; 
    border: none; 
    padding: 18px; 
    border-radius: 12px; 
    font-weight: 900; 
    cursor: pointer; 
    margin-top: 30px; 
    text-transform: uppercase; 
    letter-spacing: 1px;
}

.output-area { 
    background: rgba(0,0,0,0.2); 
    border-radius: 24px; 
    padding: 35px; 
    min-height: 800px; 
    border: 1px solid var(--border); 
}

.placeholder { 
    text-align: center; 
    margin-top: 350px; 
    color: #1e293b; 
    font-weight: 900; 
    letter-spacing: 12px; 
    text-transform: uppercase; 
    font-size: 1.4rem; 
}

.pack-card { 
    background: #0f1115; 
    padding: 30px; 
    border-radius: 20px; 
    margin-bottom: 30px; 
    border-left: 4px solid var(--holo); 
    position: relative; 
    animation: fadeIn 0.5s ease-out;
}

@keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

.copy-btn { 
    position: absolute; 
    top: 25px; 
    right: 25px; 
    background: #000; 
    color: var(--holo); 
    border: 1px solid var(--holo); 
    padding: 8px 16px; 
    border-radius: 10px; 
    font-size: 0.6rem; 
    font-weight: 900; 
    cursor: pointer; 
}

pre { font-family: 'Monaco', monospace; font-size: 0.8rem; color: #94a3b8; white-space: pre-wrap; margin: 0; margin-top: 15px; line-height: 1.6; }
.tag-label { color: var(--holo); font-size: 0.6rem; font-weight: 900; letter-spacing: 2px; text-transform: uppercase; }

footer { margin-top: 100px; padding: 50px; border-top: 1px solid var(--border); text-align: center; }
footer span { color: #1e293b; font-weight: 900; letter-spacing: 6px; font-size: 0.75rem; text-transform: uppercase; }

body.script:
//
function toggleZen() {
  document.body.classList.toggle('zen-active');
}

function resetApp() {
  if(confirm("Reset spesifikasi pengemasan?")) {
    document.getElementById('product').value = "";
    document.getElementById('output').innerHTML = '<div class="placeholder">STICKER FORGE 2026</div>';
  }
}

function forgePackage() {
  const prod = document.getElementById('product').value || "Premium Product";
  const type = document.getElementById('type').value;
  const mat = document.getElementById('material').value;
  const sty = document.getElementById('style').value;
  const out = document.getElementById('output');

  out.innerHTML = "";

  const prompts = [
    {
      tag: "STRUCTURAL BOX PROMPT",
      text: `High-end packaging design for ${prod}. \nContainer: ${type}.\nMaterial: ${mat}.\nAesthetic: ${sty}.\n\nTechnical: Flat-lay dieline view, 3D structural perspective, professional branding placement, typography layout, high-fidelity texture rendering, retail-ready presentation, 8k resolution. --v 6.1 --stylize 350`
    },
    {
      tag: "PRODUCT MOCKUP VIEW",
      text: `A professional studio product photography of ${prod} inside its ${type}. Made of ${mat} with ${sty} design elements. Soft cinematic lighting, focus on material textures, clean background, editorial catalog quality.`
    }
  ];

  prompts.forEach(p => {
    let card = document.createElement('div');
    card.className = 'pack-card';

    let tag = document.createElement('div');
    tag.className = 'tag-label';
    tag.innerText = p.tag;

    let btn = document.createElement('button');
    btn.className = 'copy-btn';
    btn.innerText = 'COPY';
    btn.onclick = () => {
      navigator.clipboard.writeText(p.text);
      btn.innerText = 'DONE';
      setTimeout(() => { btn.innerText = 'COPY'; }, 1500);
    };

    let pre = document.createElement('pre');
    pre.innerText = p.text;

    card.appendChild(tag);
    card.appendChild(btn);
    card.appendChild(pre);
    out.appendChild(card);
  });
}
//
